{
  "pains": [
    {
      "id": "pain:bounced-emails",
      "statement": "I paid for verified emails and a big chunk of them bounce, so I end up cross-checking every list before I dare send it.",
      "element": "b2b:functional:product_quality",
      "shape": {
        "surface": "Exported emails bounce at rates far above what the vendor claims; buyers report 'well over 65% bounce' and 'many of the email addresses are bad or bounced'.",
        "operational": "Every list has to be re-verified by hand or in a second tool before sending, and the campaigns that do go out run on contacts who have moved on, so reply volume and pipeline fall.",
        "personal": "The rep or founder who loaded the list owns the bounce rate and the dead campaign; they paid for the data and still do the checking work themselves."
      },
      "workflow": "Apollo People Search -> export or add to sequence -> (often) external verifier -> Apollo sequence or mailbox send; bites at the step between export and first send.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "First big send from a fresh export comes back with a wave of hard bounces.",
          "cites": ["src:1", "src:21"]
        },
        {
          "event": "A campaign underperforms and the rep traces it back to the list.",
          "cites": ["src:10"]
        }
      ],
      "who_feels": ["end_user", "economic_buyer", "technical_evaluator"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Well over 65% bounce and failed rate.",
              "cites": ["src:1"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "can mistake in data so we have cross check data for complete details",
              "cites": ["src:14"]
            },
            {
              "situation": "venting",
              "verbatim": "Some contact information is outdated and credit can runs out quickly with heavy usage that need to be improve.",
              "cites": ["src:24"]
            }
          ],
          "costs_them": "Hours re-checking lists, plus the meetings lost to bounced or wrong-person sends.",
          "fears": "Their numbers look bad because the data was bad, and nobody upstream sees the difference.",
          "dream_outcome": "Export a list and send it the same hour without a second verification pass."
        },
        "economic_buyer": {
          "says": [
            {
              "situation": "when_refusing",
              "verbatim": "BD & Sales is tough and bad data/emails make it hard to have successful long term outreach campaigns.",
              "cites": ["src:10"]
            },
            {
              "situation": "venting",
              "verbatim": "It's slow. It's clunky. It's data is inaccurate.",
              "cites": ["src:12"]
            }
          ],
          "costs_them": "Subscription spend on contacts that cannot be reached, and outbound that cannot be scaled because the inputs are unreliable.",
          "fears": "Paying a premium for a data tool that is no better than free lookups.",
          "dream_outcome": "Contact data good enough that outbound can be planned and forecast, not babysat."
        },
        "technical_evaluator": {
          "says": [
            {
              "situation": "when_comparing",
              "verbatim": "many of the email addresses are bad or bounced.",
              "cites": ["src:21"]
            }
          ],
          "costs_them": "Owning a verification layer and bounce monitoring on top of the data vendor.",
          "fears": "Bad records flowing into the CRM and reports with nobody catching them.",
          "dream_outcome": "One source of contact data they can trust without a second vendor behind it."
        }
      },
      "relief": {
        "line": "**Lists go out unchecked.** The export is good enough to send without a cross-check.",
        "says": [
          {
            "role": "end_user",
            "verbatim": "Their info database is fine, and for the most part pretty solid info in it.",
            "cites": ["src:30"]
          },
          {
            "role": "end_user",
            "verbatim": "To be frank and speak as a professional, yes, everything related to data acquisition looks good overall.",
            "cites": ["src:29"]
          }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "**Data stops being the excuse.** A year on, when outbound misses, the team argues about message and market, never about whether the emails were real.",
        "says": [],
        "gap": "Searched Trustpilot (1-3 star and recent pages), Product Hunt, RevGenius and HN; buyers describe data being 'fine' or 'solid' but nobody describes the standing change a year later. Reddit, G2 and Capterra were blocked to direct fetch."
      },
      "segments": ["seg:smb", "seg:midmarket", "seg:revops"],
      "feature_ref": "feat:waterfall",
      "cites": ["src:1", "src:10", "src:12", "src:14", "src:21", "src:24", "src:29", "src:30"],
      "priority": 1,
      "felt_evidence": {
        "kind": "complaining",
        "what": "Dated public complaints about bounce rates and inaccurate data from paying users on Trustpilot in September 2026 and March 2026, plus a July 2026 Capterra review on outdated contacts.",
        "cites": ["src:1", "src:10", "src:14", "src:24"]
      }
    },
    {
      "id": "pain:no-meetings",
      "statement": "We send thousands of emails a month and the calendar is still empty, and I can't tell what to change.",
      "element": "b2b:functional:improved_top_line",
      "shape": {
        "surface": "High send volume with zero or collapsing meetings booked.",
        "operational": "Activity metrics look busy while pipeline does not move; reporting shows what happened but not what to fix, so teams keep sending more.",
        "personal": "Reps lose the will to call and dial; founders and leaders pay a premium plan for months with nothing to show their own boss or board."
      },
      "workflow": "Apollo sequences and dialer -> reply and meeting tracking in Apollo or the CRM; bites at the weekly pipeline or bookings review.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "Months on a paid plan pass with no meetings from outbound.",
          "cites": ["src:5"]
        },
        {
          "event": "A rep's weekly bookings drop and they lose motivation to keep dialing.",
          "cites": ["src:25"]
        }
      ],
      "who_feels": ["end_user", "economic_buyer"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Have booked like 2 meetings in 2 weeks. Before that, I'd book 3-4 a week.",
              "cites": ["src:25"]
            },
            {
              "situation": "when_looking",
              "verbatim": "reporting tells me what happened but not what to change.",
              "cites": ["src:31"]
            }
          ],
          "costs_them": "Quota attainment and commission; morale.",
          "fears": "Being judged on bookings they cannot produce with the list and tools they were given.",
          "dream_outcome": "Back to a steady few meetings a week, and knowing which change got them there."
        },
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Sent 10000s of emails and did not get a single meeting after 5 months of being on their premium plan.",
              "cites": ["src:5"]
            }
          ],
          "costs_them": "Months of subscription plus rep time with no pipeline.",
          "fears": "Outbound as a channel is dead for them and the spend was wasted.",
          "dream_outcome": "Outbound that books meetings predictably enough to hire against."
        }
      },
      "relief": {
        "line": "**Meetings come back.** The week has bookings in it again, not just sends.",
        "says": [
          {
            "role": "end_user",
            "verbatim": "Have booked like 2 meetings in 2 weeks. Before that, I'd book 3-4 a week.",
            "cites": ["src:25"]
          }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "**Outbound is a channel you can plan on.** Leaders hire and forecast against it instead of wondering if it works.",
        "says": [],
        "gap": "No buyer in the sources read describes outbound becoming a reliable channel after a fix; the only after-state quote is the rep's remembered 3-4 meetings a week."
      },
      "segments": ["seg:smb", "seg:midmarket"],
      "feature_ref": "feat:harness",
      "feature_note": "GTM Harness only kills this if its research and outreach agents change targeting and message, not just add volume; the evidence here does not show the cause.",
      "cites": ["src:5", "src:25", "src:31"],
      "priority": 2,
      "felt_evidence": {
        "kind": "complaining",
        "what": "A premium-plan customer posted on Trustpilot on 2026-09-22 that months of sending produced no meetings; a rep's Reddit complaint about collapsing bookings is quoted in a July 2025 article.",
        "cites": ["src:5", "src:25"]
      }
    },
    {
      "id": "pain:wrong-numbers",
      "statement": "Half my call block is switchboards and wrong numbers, so I dial all day and barely talk to anyone.",
      "element": "b2b:ease_of_doing_business:time_savings",
      "shape": {
        "surface": "Phone numbers point to the wrong business or to generic corporate lines a rep could find on Google.",
        "operational": "Dial blocks are spent on dead and gatekept lines, connect rates fall, and phone credits are spent on numbers that never reach the person.",
        "personal": "The SDR's activity looks fine while conversations do not happen, which wears them down and costs them meetings."
      },
      "workflow": "Apollo contact reveal (mobile credits) -> Apollo dialer or a separate dialer -> CRM call logging; bites in the morning call block.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "A call block where the revealed numbers ring the wrong company or a switchboard.",
          "cites": ["src:2", "src:23"]
        }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "They have associated wrong numbers with wrong business.",
              "cites": ["src:2"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "The phone numbers are highly inaccurate, and most of the ones provided are just generic corporate lines",
              "cites": ["src:23"]
            }
          ],
          "costs_them": "Call-block hours and phone credits spent reaching nobody.",
          "fears": "Missing their conversation and meeting targets because of numbers they cannot control.",
          "dream_outcome": "A call list where the person who answers is the person they meant to call."
        }
      },
      "relief": {
        "line": "**Dials reach people.** The number on the record rings the person on the record.",
        "says": [],
        "gap": "Searched Trustpilot, Product Hunt, Capterra quotes reproduced on cleanlist.ai and HN; no buyer quote describes phone data that works. Reddit and G2 were blocked to direct fetch."
      },
      "euphoria": {
        "line": "**Calling becomes the best hour of the day.** Reps run phone-first outbound because conversations are reliable.",
        "says": [],
        "gap": "No source read describes the long-term after state for phone data."
      },
      "segments": ["seg:midmarket", "seg:smb"],
      "feature_ref": "feat:waterfall",
      "feature_note": "Waterfall enrichment across providers is what would fix number accuracy; the parallel dialer only makes bad lists fail faster.",
      "cites": ["src:2", "src:23"],
      "priority": 3,
      "felt_evidence": {
        "kind": "complaining",
        "what": "A Trustpilot reviewer on 2026-09-25 complains Apollo tied wrong numbers to the wrong business; a Capterra reviewer (March 2025) calls the numbers generic corporate lines.",
        "cites": ["src:2", "src:23"]
      }
    },
    {
      "id": "pain:credits-burn",
      "statement": "Credits vanish on lookups that fail, they don't roll over, and I get hit with limits while I still have credits left.",
      "element": "b2b:table_stakes:acceptable_price",
      "shape": {
        "surface": "Credits are spent on failed enrichments and records already paid for, expire monthly, and trigger limits and upsell prompts.",
        "operational": "Teams ration lookups, campaigns stall mid-run, and support threads drag on while the work waits.",
        "personal": "The person holding the budget feels nickel-and-dimed and ends up arguing with support instead of prospecting."
      },
      "workflow": "Apollo search -> reveal or enrich (credit charge) -> retry or waterfall (more credits) -> support ticket; bites when a bulk enrichment or export runs.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "A bulk enrichment fails and still consumes credits.",
          "cites": ["src:9"]
        },
        {
          "event": "Support suggests re-running records through waterfall enrichment for more credits.",
          "cites": ["src:4"]
        },
        {
          "event": "Month end, unused credits disappear.",
          "cites": ["src:6"]
        }
      ],
      "who_feels": ["economic_buyer", "end_user"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "when_refusing",
              "verbatim": "The credits don't roll over and they are expensive as hell.",
              "cites": ["src:6"]
            },
            {
              "situation": "venting",
              "verbatim": "but it kept failing - burning 25 records and multiple credits - then attempting to upcharge me over and over.",
              "cites": ["src:9"]
            }
          ],
          "costs_them": "Paying for failed and repeat lookups; overage and upgrade pressure.",
          "fears": "A bill they cannot predict for data they cannot use.",
          "dream_outcome": "Pay only for records that come back usable, with nothing expiring."
        },
        "end_user": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "I am getting a limit, EVEN THOUGH I still have credits.",
              "cites": ["src:7"]
            },
            {
              "situation": "venting",
              "verbatim": "I was told the full data existed on the backend.",
              "cites": ["src:4"]
            }
          ],
          "costs_them": "Blocked mid-task and stuck in support loops.",
          "fears": "Running out of credits mid-campaign and missing the window.",
          "dream_outcome": "Search and reveal without watching a meter."
        }
      },
      "relief": {
        "line": "**No more credit math.** A failed lookup costs nothing and the month's balance carries over.",
        "says": [],
        "gap": "Reviewers name the fix they want by leaving (one is moving to a provider at 'half the price'), but none describes the after state in their own words."
      },
      "euphoria": {
        "line": "**Data spend is boring.** Finance stops asking about the data line because it is predictable.",
        "says": [],
        "gap": "No source read describes this."
      },
      "segments": ["seg:smb", "seg:midmarket"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company kills this; it is the credit model itself (charge only on success, rollover, clear limits).",
      "cites": ["src:4", "src:6", "src:7", "src:9", "src:24"],
      "priority": 4,
      "felt_evidence": {
        "kind": "switching",
        "what": "A Trustpilot reviewer on 2026-10-02 says they are leaving Apollo for Prospeo over credit price and no rollover; others complain of credits burned on failed enrichments in June and September 2026.",
        "cites": ["src:6", "src:9", "src:4"]
      }
    },
    {
      "id": "pain:domain-burned",
      "statement": "Our deliverability tanked and now I can't even send a normal email from our domain.",
      "element": "b2b:ease_of_doing_business:risk_reduction",
      "shape": {
        "surface": "Mail warming and sequence sends get flagged; regular company email starts landing in spam.",
        "operational": "Outbound stops, and the fix can mean buying and warming a new domain or brand.",
        "personal": "The founder or rep who turned on the sequence is blamed for breaking company email."
      },
      "workflow": "Linking mailboxes and warmup in Apollo -> sequences at volume -> Gmail or Outlook filters; bites days or weeks after volume ramps.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "Google flags the sending domain after warmup or a volume ramp.",
          "cites": ["src:8"]
        },
        {
          "event": "Sending far more than the domain can carry because nothing stops it.",
          "cites": ["src:22"]
        }
      ],
      "who_feels": ["end_user", "economic_buyer"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "My email deliverability has tanked and I can't even send a regular email now.",
              "cites": ["src:8"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "the tool will happily let you send far more than you should.",
              "cites": ["src:22"]
            }
          ],
          "costs_them": "Outbound offline, plus normal email to customers going to spam.",
          "fears": "Having to rebuild on a new domain or brand.",
          "dream_outcome": "Send at the volume they need without risking the company's main inbox."
        },
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "My email deliverability has tanked and I can't even send a regular email now.",
              "cites": ["src:8"]
            }
          ],
          "costs_them": "A new domain, warmup time and lost weeks of outbound.",
          "fears": "A sales tool damaging how the whole company's email is received.",
          "dream_outcome": "Guardrails that keep outbound from touching company email."
        }
      },
      "relief": {
        "line": "**Inbox stays clean.** Sequences run and company email still lands.",
        "says": [],
        "gap": "No buyer in the sources read describes recovered deliverability."
      },
      "euphoria": {
        "line": "**Volume without fear.** Teams scale sends knowing the tool stops them before the domain burns.",
        "says": [],
        "gap": "No source read describes this."
      },
      "segments": ["seg:smb"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company covers deliverability; what would kill it is send caps and domain health guardrails inside Workspace.",
      "cites": ["src:8", "src:22"],
      "priority": 5,
      "felt_evidence": {
        "kind": "complaining",
        "what": "A paying user posted on Trustpilot on 2026-05-18 that Apollo's mail warming got their domain flagged by Google.",
        "cites": ["src:8"]
      }
    },
    {
      "id": "pain:seats-locked",
      "statement": "We're paying for seats nobody uses and the contract won't let us cut them until renewal.",
      "element": "b2b:ease_of_doing_business:flexibility",
      "shape": {
        "surface": "Unused or never-activated seats keep billing; no downgrade, seat reduction or pause offered.",
        "operational": "When headcount or plans change, spend does not; renewal becomes a benchmarking fight.",
        "personal": "The leader who signed owns a line item they cannot defend and a vendor fight they did not plan for."
      },
      "workflow": "Annual Organization or Enterprise order form -> headcount change -> billing and collections emails -> renewal negotiation; bites when a team shrinks or a client is lost.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "Losing a major client or cutting the BD function mid-contract.",
          "cites": ["src:3"]
        },
        {
          "event": "A ~100-seat renewal coming up with no pricing benchmark.",
          "cites": ["src:15"]
        }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "one of four paid seats never even activated.",
              "cites": ["src:3"]
            },
            {
              "situation": "when_looking",
              "verbatim": "We’re ~100 seats and heading into renewal - trying to benchmark market pricing.",
              "cites": ["src:15"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "Read the order form carefully before signing, and do not count on flexibility if things change.",
              "cites": ["src:32"]
            }
          ],
          "costs_them": "Full contract value for seats with zero usage.",
          "fears": "Being locked in when the business changes, and getting fleeced at renewal.",
          "dream_outcome": "Spend that moves with headcount and usage."
        }
      },
      "relief": {
        "line": "**Seats follow the team.** When the team shrinks, the bill does too.",
        "says": [],
        "gap": "No buyer in the sources read describes a vendor that flexed seats for them."
      },
      "euphoria": {
        "line": "**Signing is low-risk.** Leaders commit early because the contract bends when plans change.",
        "says": [],
        "gap": "No source read describes this."
      },
      "segments": ["seg:smb", "seg:midmarket"],
      "feature_ref": null,
      "feature_note": "Not a product feature; contract terms (seat reduction, pause, usage-based pricing) would kill it.",
      "cites": ["src:3", "src:15", "src:32"],
      "priority": 6,
      "felt_evidence": {
        "kind": "complaining",
        "what": "A CEO posted on Trustpilot on 2026-10-02 about being sent to collections for an unused four-seat plan; a RevOps lead with ~100 seats asked peers for renewal benchmarks on 2026-01-28.",
        "cites": ["src:3", "src:15"]
      }
    },
    {
      "id": "pain:crm-dirty",
      "statement": "Every tool we plug in pushes duplicates and half-filled records into the CRM, and someone has to clean it up by hand.",
      "element": "b2b:ease_of_doing_business:integration",
      "shape": {
        "surface": "Missing, duplicate and inaccurate CRM records; integrations that do not sync the way the team needs.",
        "operational": "RevOps runs recurring cleanup and merge projects before reporting, forecasting or territory work can be trusted.",
        "personal": "The RevOps owner spends their time on janitorial work and takes the blame when reports are wrong."
      },
      "workflow": "Apollo or other enrichment tools -> HubSpot or Salesforce sync -> duplicate rules and merge queues -> reporting and territory carving; bites before every forecast and territory change.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "A reporting, forecasting or territory-carving project exposes duplicate accounts.",
          "cites": ["src:16"]
        },
        {
          "event": "Connecting a sales tool's HubSpot integration.",
          "cites": ["src:11"]
        }
      ],
      "who_feels": ["technical_evaluator", "end_user"],
      "by_role": {
        "technical_evaluator": {
          "says": [
            {
              "situation": "to_their_boss",
              "verbatim": "Proactively identify missing, duplicate, or inaccurate CRM data and execute cleanup.",
              "cites": ["src:17"]
            },
            {
              "situation": "to_their_boss",
              "verbatim": "Identify and merge duplicate Account records, triaging an existing merge request process.",
              "cites": ["src:16"]
            }
          ],
          "costs_them": "Headcount and contractor hours spent on cleanup.",
          "fears": "Leadership acting on reports built on duplicate and wrong records.",
          "dream_outcome": "Enrichment that lands clean in the CRM so cleanup stops being a standing job."
        },
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Possibly the most useless Hubspot integration I've ever had to deal with.",
              "cites": ["src:11"]
            }
          ],
          "costs_them": "Re-entering and reconciling activity between the sales tool and the CRM.",
          "fears": "Their activity and pipeline not showing up where their manager looks.",
          "dream_outcome": "Work in one tool and have the CRM be right."
        }
      },
      "relief": {
        "line": "**Merge queue empties.** New records arrive matched and complete.",
        "says": [],
        "gap": "Job posts describe the cleanup as ongoing; HubSpot community threads with RevOps voice were blocked (403), and Reddit could not be fetched."
      },
      "euphoria": {
        "line": "**The CRM is trusted.** Forecasts and territories get built without a cleanup project first.",
        "says": [],
        "gap": "No source read describes this."
      },
      "segments": ["seg:revops"],
      "feature_ref": null,
      "feature_note": "Waterfall enrichment fills gaps but nothing in brain/company dedupes or matches before creating CRM records; that sync behavior is what would kill it.",
      "cites": ["src:11", "src:16", "src:17"],
      "priority": 7,
      "felt_evidence": {
        "kind": "hiring",
        "what": "Webflow hired a contract RevOps Data Hygiene Coordinator at $25/hour to merge duplicate Salesforce accounts (posted around March 2026); Chromatic posted a $110k-120k RevOps role whose duties center on CRM cleanup (around January 2026).",
        "cites": ["src:16", "src:17"]
      }
    },
    {
      "id": "pain:tool-sprawl",
      "statement": "We pay for a pile of sales tools that all do the same few things, and reps juggle them instead of selling.",
      "element": "b2b:ease_of_doing_business:simplification",
      "shape": {
        "surface": "Many overlapping tools across data, sequencing and dialing, each renewing on its own date.",
        "operational": "Overlapping spend, reps switching between tools, and renewals negotiated one at a time without a plan.",
        "personal": "Leaders defend a growing stack budget; reps feel buried in tools."
      },
      "workflow": "ZoomInfo or Apollo for data, Outreach or similar for sequences, a dialer, Clay for orchestration, the CRM; bites at each renewal and in the rep's daily tab switching.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "Renewals landing at different times of the year.",
          "cites": ["src:27"]
        }
      ],
      "who_feels": ["economic_buyer", "technical_evaluator", "end_user"],
      "by_role": {
        "technical_evaluator": {
          "says": [
            {
              "situation": "when_looking",
              "verbatim": "Also I'd avoid looking at tools in a siloed way, I totally get that renewals comes at different time of the year",
              "cites": ["src:27"]
            }
          ],
          "costs_them": "Paying several vendors for the same capability.",
          "fears": "Locking into a stack that is outdated next year.",
          "dream_outcome": "Fewer tools that cover the job without overlap."
        },
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "However, 66% of sales reps say they're overwhelmed by the number of tools.",
              "cites": ["src:20"]
            }
